oreach($rows as $r):?><tr><td><?=htmlspecialchars($r['nomor_sk'])?></td><td><?=date('d/m/Y',strtotime($r['tanggal_sk']))?></td><td><?=htmlspecialchars($r['nama_perusahaan'])?></td><td><?=htmlspecialchars($r['nomor_ippkh'])?></td><td><?=htmlspecialchars($r['status_sk'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5" class="text-center py-4">Belum ada SK.</td></tr><?php endif?></tbody></table></div></div></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
